CREATE TABLE public.staff_name_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL, user_id uuid NOT NULL, old_name text, new_name text, changed_by uuid, changed_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.staff_name_history TO authenticated;
GRANT ALL ON public.staff_name_history TO service_role;
ALTER TABLE public.staff_name_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own names or company user admins" ON public.staff_name_history FOR SELECT TO authenticated USING (user_id=auth.uid() OR (company_id=public.my_company_id() AND public.has_perm('users','view')));
CREATE FUNCTION public.staff_name_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF OLD.user_type='staff' AND NEW.full_name IS DISTINCT FROM OLD.full_name THEN INSERT INTO public.staff_name_history(company_id,user_id,old_name,new_name,changed_by) VALUES(NEW.company_id,NEW.id,OLD.full_name,NEW.full_name,auth.uid()); END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.staff_name_audit() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER staff_name_audit AFTER UPDATE OF full_name ON public.user_profiles FOR EACH ROW EXECUTE FUNCTION public.staff_name_audit();
CREATE TRIGGER staff_name_history_immutable BEFORE UPDATE OR DELETE ON public.staff_name_history FOR EACH ROW EXECUTE FUNCTION public.cc72_history_immutable();
CREATE FUNCTION public.set_my_name(p_name text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n text:=btrim(p_name); BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'not_signed_in'; END IF; IF n IS NULL OR length(regexp_replace(n,'[^[:alpha:]]','','g')) < 2 THEN RAISE EXCEPTION 'name_too_short'; END IF; UPDATE public.user_profiles SET full_name=n WHERE id=auth.uid() AND is_active AND user_type='staff'; IF NOT FOUND THEN RAISE EXCEPTION 'not_staff'; END IF; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.set_my_name(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.set_my_name(text) TO authenticated;
CREATE FUNCTION public.remove_my_photo() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'not_signed_in'; END IF; UPDATE public.user_profiles SET photo_url=NULL WHERE id=auth.uid() AND is_active AND user_type='staff'; IF NOT FOUND THEN RAISE EXCEPTION 'not_staff'; END IF; END $$;
REVOKE ALL ON FUNCTION public.remove_my_photo() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.remove_my_photo() TO authenticated;
CREATE OR REPLACE FUNCTION public.gate_register_timeline(p_from timestamptz,p_to timestamptz) RETURNS TABLE(at timestamptz,kind text,title text,detail text,by_name text,entry_id uuid,entry_type text,vehicle_no text,photo_path text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
WITH ok AS (SELECT public.has_perm('gate','create') AS v,my_company_id() AS cid), rws AS (
SELECT e.in_at AS at,'entry_in'::text AS kind,CASE WHEN e.staff_user_id IS NOT NULL THEN coalesce(sp.full_name,e.name) ELSE e.name END AS title,concat_ws(' · ',e.mobile,e.from_place,e.purpose) AS detail,e.in_by AS who,e.id AS eid,e.entry_type AS et,e.vehicle_no AS vno,CASE WHEN e.staff_user_id IS NOT NULL THEN sp.photo_url ELSE e.photo_path END AS ph FROM gate_entries e LEFT JOIN user_profiles sp ON sp.id=e.staff_user_id,ok WHERE e.company_id=ok.cid
UNION ALL SELECT e.out_at,'entry_out',CASE WHEN e.staff_user_id IS NOT NULL THEN coalesce(sp.full_name,e.name) ELSE e.name END,e.mobile,e.out_by,e.id,e.entry_type,e.vehicle_no,CASE WHEN e.staff_user_id IS NOT NULL THEN sp.photo_url ELSE coalesce(e.out_photo_path,e.photo_path) END FROM gate_entries e LEFT JOIN user_profiles sp ON sp.id=e.staff_user_id,ok WHERE e.company_id=ok.cid AND e.out_at IS NOT NULL
UNION ALL SELECT t.gate_out_at,'vehicle_out',t.trip_no,coalesce(d.full_name,t.hired_driver_name),t.gate_out_by,NULL::uuid,'trip',v.reg_no,d.photo_url FROM trips t LEFT JOIN vehicles v ON v.id=t.vehicle_id LEFT JOIN user_profiles d ON d.id=t.driver_user_id,ok WHERE t.company_id=ok.cid AND t.gate_out_at IS NOT NULL
UNION ALL SELECT t.gate_in_at,'vehicle_in',t.trip_no,concat_ws(' · ',coalesce(d.full_name,t.hired_driver_name),CASE WHEN t.gate_in_manual THEN 'manual' END),t.gate_in_by,NULL::uuid,'trip',v.reg_no,d.photo_url FROM trips t LEFT JOIN vehicles v ON v.id=t.vehicle_id LEFT JOIN user_profiles d ON d.id=t.driver_user_id,ok WHERE t.company_id=ok.cid AND t.gate_in_at IS NOT NULL)
SELECT r.at,r.kind,r.title,r.detail,u.full_name,r.eid,r.et,r.vno,r.ph FROM rws r LEFT JOIN user_profiles u ON u.id=r.who,ok WHERE ok.v AND r.at>=p_from AND r.at<p_to ORDER BY r.at DESC LIMIT 500 $$;